function largestOddNumber(num) {
  for (let i = num.length - 1; i >= 0; i--) {
    const char = num[i];
    if (char === '1' || char === '3' || char === '5' || char === '7' || char === '9') {
      return num.substring(0, i + 1);
    }
  }
  return '';
}
